/**
 * @summary List saved images
 */
export const getListImagesUrl = (params?: ListImagesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/images?${stringifiedParams}`
    : `/api/images`;
};

export const listImages = async (
  params?: ListImagesParams,
  options?: RequestInit,
): Promise<SavedImage[]> => {
  return customFetch<SavedImage[]>(getListImagesUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListImagesQueryKey = (params?: ListImagesParams) => {
  return [`/api/images`, ...(params ? [params] : [])] as const;
};

export const getListImagesQueryOptions = <
  TData = Awaited<ReturnType<typeof listImages>>,
  TError = ErrorType<unknown>,
>(
  params?: ListImagesParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listImages>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListImagesQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listImages>>> = ({
    signal,
  }) => listImages(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listImages>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListImagesQueryResult = NonNullable<
  Awaited<ReturnType<typeof listImages>>
>;
export type ListImagesQueryError = ErrorType<unknown>;

/**
 * @summary List saved images
 */

export function useListImages<
  TData = Awaited<ReturnType<typeof listImages>>,
  TError = ErrorType<unknown>,
>(
  params?: ListImagesParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listImages>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListImagesQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

